import{l as t,b as n,c as s,g as r}from"./chunks/framework.Du5_AGGE.js";const d=JSON.parse('{"title":"古代汉语","description":"","frontmatter":{"title":"古代汉语","subTitle":"通论语法总表","author":"oasis","date":"2026-10-20T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/classical-chinese/1-2.md","filePath":"articles/books/classical-chinese/1-2.md"}'),g={name:"articles/books/classical-chinese/1-2.md"};function l(p,o,i,e,b,u){return n(),s("div",null,[...o[0]||(o[0]=[r('<p>术语、定义和例句按下面的顺序排列：词类、词类活用、代词特殊结构、基本句型、特殊语序、省略句、兼词、特殊句式（连动、递系、“之”取独）、词汇构词。</p><h2 id="一、词类系统" tabindex="-1">一、词类系统</h2><h3 id="一-实词" tabindex="-1">（一）实词</h3><h4 id="_1-名词" tabindex="-1">1. 名词</h4><p>表示人、事物、地点。作主语、宾语、定语。</p><blockquote><p><strong>齐侯纳之，以为诸公子之傅</strong>（《鲁施氏有二子》）</p></blockquote><p>侯、公子、傅，名词。</p><h4 id="_2-动词" tabindex="-1">2. 动词</h4><p>动作、变化、判断；作谓语，分及物 / 不及物。</p><blockquote><p><strong>孟氏之一子之秦，以术干秦王</strong></p></blockquote><p>干：动词，干谒求仕；之：动词，前往（王力重点：动词“之”≠助词）。</p><h4 id="_3-形容词" tabindex="-1">3. 形容词</h4><p>性质、状态；作定语、谓语、状语。</p><blockquote><p><strong>孟氏父子舍然无愠容</strong></p></blockquote><p>愠：形容词，恼怒。</p><h4 id="_4-数词" tabindex="-1">4. 数词</h4><p>基数、序数、分数、约数、虚数。</p><ul><li>基数：<strong>鲁施氏有二子</strong>（二子，两个儿子）</li><li>分数：<strong>藉第令毋斩，而戍死者固十六七</strong>（《史记·陈涉世家》，十分之六七）</li><li>虚数：<strong>千千万臣而无数者也</strong>（《九方皋相马》，千万：虚数，极多）</li></ul><h4 id="_5-量词" tabindex="-1">5. 量词</h4><p>名量词、动量词。上古汉语量词不发达。</p><ul><li>名量：<strong>一箪食，一瓢饮</strong>（《论语》）</li><li>动量：<strong>三战三北</strong>（三次作战，三次败逃）</li></ul><h4 id="_6-代词" tabindex="-1">6. 代词</h4><p>王力单列重点。</p><ul><li><strong>人称代词</strong>：吾、我、余、予（第一人称）；汝、尔、若（第二人称）；<strong>其、之</strong>（第三人称）。例：<strong>子之年长矣</strong>（子：第二人称代词，您，《九方皋相马》）</li><li><strong>指示代词</strong>：此、是、斯（近指，这）；彼、夫（远指，那）。例：<strong>是灭亡之道</strong>（是：指示代词，这，《鲁施氏有二子》）</li><li><strong>疑问代词</strong>：谁、孰、何、奚、安、焉。例：<strong>又何马之能知也</strong>（何：疑问代词，什么，《九方皋相马》）</li></ul><p>者、所是<strong>特殊指示代词</strong>，构成名词性短语。</p><ol><li><strong>者字结构</strong>：动词 / 形容词 + 者 → “……的人 / 物”（动作发出者，施事）。公式：V + 者。 <ul><li><strong>好学者以术干齐侯</strong>（好学者：喜爱学问的人）</li><li><strong>子所使求马者</strong>（求马者：寻找马匹的人）</li></ul></li><li><strong>所字结构</strong>：所 + 动词 → “被……的事物”（动作对象，受事）。公式：所 + V。 <ul><li><strong>所务兵食而已</strong>（所务：所致力的事务，《鲁施氏有二子》）</li><li><strong>若皋之所观，天机也</strong>（所观：所观察到的东西，《九方皋相马》）</li></ul></li></ol><h3 id="二-虚词" tabindex="-1">（二）虚词</h3><h4 id="_1-副词" tabindex="-1">1. 副词</h4><p>程度、范围、时间、否定、情态。</p><ul><li><strong>否定副词</strong>：不、弗、毋、勿。例：<strong>色物牝牡尚弗能知</strong>（弗：不）</li><li><strong>范围副词</strong>：皆、尽、悉。例：<strong>臣之子皆下才也</strong>（皆：都）</li><li><strong>时间副词</strong>：既、已。例：<strong>既反，孟氏之父子叩胸而让施氏</strong>（既：……之后）</li><li><strong>情态副词</strong>：固、乃。例：<strong>是乃其所以千万臣而无数者也</strong>（乃：就是）</li></ul><h4 id="_2-介词" tabindex="-1">2. 介词</h4><p>于（乎）、以、为、与。引出对象、工具、处所、原因。介宾常后置。</p><ul><li><strong>于</strong>：<strong>窘于贫</strong>（于，引施事，被贫穷困迫）</li><li><strong>以</strong>：<strong>以术干齐侯</strong>（以，用，凭借）</li><li><strong>乎 = 于</strong>：<strong>贵乎马者也</strong>（乎，比）</li></ul><h4 id="_3-连词" tabindex="-1">3. 连词</h4><p>而、以、则、且、虽、若、故。承接 / 转折 / 递进 / 假设。</p><ul><li><strong>而（承接）</strong>：<strong>遂刖之，而还诸鲁</strong>（而后，表先后）</li><li><strong>而（转折）</strong>：<strong>子道与吾同，而功与吾异</strong>（但是）</li><li><strong>若（假设）</strong>：<strong>若用仁义治吾国，是灭亡之道</strong>（如果）</li></ul><h4 id="_4-语气词" tabindex="-1">4. 语气词</h4><p>句末：</p><ul><li><strong>也</strong>：表判断、肯定。例：<strong>果天下之马也</strong></li><li><strong>矣</strong>：已然、将然。例：<strong>已得之矣</strong>（已经找到了）</li><li><strong>乎</strong>：疑问。例：<strong>子姓有可以求马者乎？</strong></li><li><strong>哉</strong>：感叹。例：<strong>焉往而不穷哉？</strong></li></ul><p>句首 / 句中：夫、盖、惟（维）。</p><blockquote><p><strong>夫战，勇气也</strong>（夫，句首发语词）</p></blockquote><h4 id="_5-词头、词尾" tabindex="-1">5. 词头、词尾</h4><ul><li>形容词词尾 <strong>然、如、尔</strong>，译为“……的样子”。例：<strong>伯乐喟然太息</strong>（喟然：长叹的样子）</li><li>词头：有，用于国名、族名前，<strong>有虞、有周</strong></li></ul><h2 id="二、词类活用" tabindex="-1">二、词类活用</h2><blockquote><p>定义：本是甲类词，在句中临时具备乙类词语法功能。</p></blockquote><h3 id="_1-名词用作一般动词" tabindex="-1">1. 名词用作一般动词</h3><p>名词临时充当谓语，表动作。</p><blockquote><p><strong>遂宫而放之</strong>（宫，名词，宫刑；活用动词：施加宫刑）</p></blockquote><h3 id="_2-名词作状语" tabindex="-1">2. 名词作状语</h3><p>名词放在动词前修饰谓语。四类翻译：像……一样；在……；从……；按……。</p><blockquote><p><strong>蚕食诸侯</strong>（《战国策》，蚕：像蚕一样吞食）</p></blockquote><h3 id="_3-使动用法" tabindex="-1">3. 使动用法</h3><p>主语<strong>使宾语</strong>产生动作或状态，客观致使。</p><ol><li><strong>动词使动</strong>：<strong>项伯杀人，臣活之</strong>（活之 = 使之活，使他活下来）</li><li><strong>形容词使动</strong>：<strong>禄富其家，爵荣其亲</strong>（富其家 = 使其家富；荣其亲 = 使其亲荣耀，《鲁施氏有二子》）</li><li><strong>名词使动</strong>：<strong>纵江东父兄怜而王我</strong>（王我：使我为王，《史记》）</li></ol><h3 id="_4-意动用法" tabindex="-1">4. 意动用法</h3><p>主语<strong>主观认为宾语</strong>怎么样，主观认定，不改变客观事物。</p><ol><li><strong>形容词意动</strong>：<strong>吾妻之美我者，私我也</strong>（美我：以我为美，认为我美，《邹忌讽齐王纳谏》）</li><li><strong>名词意动</strong>：<strong>侣鱼虾而友麋鹿</strong>（友麋鹿：把麋鹿当成朋友，《赤壁赋》）</li></ol><p>辨析：使动是让宾语发生变化；意动是心里把宾语看成什么。</p><h2 id="三、三大基本句型" tabindex="-1">三、三大基本句型</h2><p>判断句、叙述句、描写句（王力通论 7、8）。</p><h3 id="_1-判断句" tabindex="-1">1. 判断句</h3><p>上古汉语<strong>没有系词“是”</strong>，“是”是指示代词。判断依靠语气词、副词。</p><p>① ……者，……也。</p><blockquote><p><strong>廉颇者，赵之良将也。</strong></p></blockquote><p>② ……，……也（最常见）</p><blockquote><p><strong>臣之子皆下才也。</strong>（《九方皋相马》）</p></blockquote><p>③ ……，……者也</p><blockquote><p><strong>是乃其所以千万臣而无数者也。</strong></p></blockquote><p>④ 乃 / 则 / 即……也（副词加强判断）</p><blockquote><p><strong>若皋之所观，天机也。</strong></p></blockquote><p>⑤ 否定判断：<strong>非</strong></p><blockquote><p><strong>非行之谬也</strong>（不是做法的错误，《鲁施氏有二子》）</p></blockquote><h3 id="_2-叙述句" tabindex="-1">2. 叙述句</h3><p>动词作谓语，叙述动作事件，内含被动式、双宾语。</p><h4 id="_1-被动表示法" tabindex="-1">（1）被动表示法</h4><p>王力四种被动句式。</p><p>① <strong>于字句</strong>：动词 + 于（引出施事，被……）</p><blockquote><p><strong>而窘于贫</strong>（被贫穷困迫）</p></blockquote><p>② <strong>为字句</strong>：为 + 施事 + 动词</p><blockquote><p><strong>身死人手，为天下笑</strong>（被天下人耻笑）</p></blockquote><p>③ <strong>为……所……</strong></p><blockquote><p><strong>若属皆且为所虏</strong>（《鸿门宴》，被俘虏）</p></blockquote><p>④ <strong>见 / 见于</strong></p><blockquote><p><strong>诚恐见欺于王而负赵</strong>（被大王欺骗）</p></blockquote><p>意念被动（无标记）：<strong>先日所用</strong>（所用：被采用的道术）</p><h4 id="_2-双宾语结构" tabindex="-1">（2）双宾语结构</h4><p>动词带两个宾语：间接宾语（人）、直接宾语（物）。常见动词：告、语、赐、遗、予。</p><blockquote><p><strong>二子以实告孟氏</strong></p></blockquote><p>完整说法是“告孟氏以实”：告（间接宾语：孟氏）（直接宾语：实）。</p><blockquote><p><strong>公赐之食</strong>（《左传》，赐给他食物）</p></blockquote><h3 id="_3-描写句" tabindex="-1">3. 描写句</h3><p>形容词作谓语，描写性质状态。</p><blockquote><p><strong>孟氏父子舍然无愠容</strong></p></blockquote><p>以形容词性短语描写主语状态。</p><h2 id="四、特殊语序" tabindex="-1">四、特殊语序</h2><p>常规语序是主—谓—宾，下面是变式。</p><h3 id="_1-宾语前置" tabindex="-1">1. 宾语前置</h3><p>王力三大类。</p><p>① 否定句，代词作宾语，前置。格式：否定词 + 代词宾语 + 动词。</p><blockquote><p><strong>古之人不余欺也</strong>（不余欺 = 不欺余，不欺骗我）</p></blockquote><p>② 疑问句，疑问代词作宾语，前置。</p><blockquote><p><strong>焉往而不穷哉</strong>（焉，疑问代词；焉往 = 往焉，去往哪里，《鲁施氏有二子》）</p></blockquote><p>③ <strong>之 / 是</strong> 作为提宾标志，把宾语提前。</p><blockquote><p><strong>又何马之能知也</strong>（何马之能知 = 能知何马，《九方皋相马》） <strong>唯利是图</strong>（唯图利）</p></blockquote><h3 id="_2-介宾短语后置" tabindex="-1">2. 介宾短语后置</h3><p>介词「于、以、乎」构成介宾，本是状语，放在动词或形容词后面，现代汉语要移到前面。</p><ul><li><strong>可告以良马</strong> = 可以以良马告之（把识别良马的方法告诉他）</li><li><strong>乃有贵乎马者也</strong> = 乃有贵于马者（比马更珍贵）</li></ul><h3 id="_3-定语后置" tabindex="-1">3. 定语后置</h3><p>格式 1：中心词 + 之 + 定语 + 者</p><blockquote><p><strong>马之千里者</strong>（千里马）</p></blockquote><p>格式 2：中心词 + 者</p><blockquote><p><strong>求人可使报秦者</strong>（寻找可以出使回复秦国的人）</p></blockquote><h3 id="_4-谓语前置" tabindex="-1">4. 谓语前置</h3><p>主谓倒装，用于感叹、疑问，强调谓语。</p><blockquote><p><strong>败矣，子所使求马者！</strong>（正常语序：子所使求马者败矣。你派去找马的人太差劲了！《九方皋相马》） <strong>甚矣，汝之不惠！</strong>（《愚公移山》）</p></blockquote><h2 id="五、省略句" tabindex="-1">五、省略句</h2><p>上古极普遍，凭上下文补足成分。</p><ol><li><p><strong>省略主语</strong></p><blockquote><p><strong>（九方皋）三月而反报曰</strong></p></blockquote><p>承前省略主语。</p></li><li><p><strong>省略宾语</strong>（“之”经常省略）</p><blockquote><p><strong>齐侯纳之，以为诸公子之傅</strong></p></blockquote><p>以为 = 以（之）为，省略宾语“之”。</p></li><li><p><strong>省略介词</strong>（于、以）</p><blockquote><p><strong>将军战河北</strong></p></blockquote><p>战（于）河北，在黄河以北作战。</p></li><li><p><strong>省略谓语</strong></p><blockquote><p><strong>一鼓作气，再（鼓）而衰，三（鼓）而竭</strong>（《曹刿论战》）</p></blockquote></li></ol><h2 id="六、兼词" tabindex="-1">六、兼词</h2><p>一字等于两个词，合音。</p><ol><li><p><strong>诸 = 之 + 于</strong>（之于）</p><blockquote><p><strong>遂刖之，而还诸鲁</strong> = 还之于鲁，送他回到鲁国</p></blockquote></li><li><p><strong>焉 = 于 + 之</strong>（于此，于彼，在这 / 那里）</p><blockquote><p><strong>三人行，必有我师焉</strong>，必有我师于此</p></blockquote></li><li><p><strong>盍 = 何 + 不</strong>（何不）</p><blockquote><p><strong>盍各言尔志？</strong>（何不各自说说你们的志向）</p></blockquote></li></ol><h2 id="七、其他重要句法结构" tabindex="-1">七、其他重要句法结构</h2><h3 id="_1-连动式" tabindex="-1">1. 连动式</h3><p>同一主语，先后连续多个谓语动作。</p><blockquote><p><strong>孟氏之一子之秦，以术干秦王</strong></p></blockquote><p>主语“一子”，两个连续动作：前往秦国，用道术求秦王任用。</p><h3 id="_2-递系式" tabindex="-1">2. 递系式</h3><p>兼语句：前一动词的宾语，同时是后一分句的主语。</p><blockquote><p><strong>使行求马</strong> = 使（之）行求马</p></blockquote><p>“之”作“使”的宾语，又是“行求马”的主语。</p><h3 id="_3-之-取消句子独立性" tabindex="-1">3. “之”取消句子独立性</h3><p>主谓之间加「之」，使主谓句变成名词性词组，作主语或宾语。</p><blockquote><p><strong>羡施氏之有</strong></p></blockquote><p>原本主谓：施氏有（施氏富有）；加入“之”后成为“施氏之有”，名词短语，充当动词“羡”的宾语。</p><blockquote><p><strong>孤之有孔明，犹鱼之有水也</strong></p></blockquote><h2 id="八、构词" tabindex="-1">八、构词</h2><ol><li><strong>单音词</strong>：一个字一个词。例：<strong>禄、爵、穷、谬</strong></li><li><strong>复音词</strong><ul><li><strong>连绵词</strong>（双声、叠韵，不可拆分）：<strong>喟然、参差、窈窕</strong>。喟然：叠韵连绵，长叹貌。</li><li><strong>偏义复词</strong>：两个字，词义只取其中一个。例：<strong>昼夜勤作息</strong>（作息，只取“作”，劳作）</li></ul></li></ol>',137)])])}const h=t(g,[["render",l]]);export{d as __pageData,h as default};
